     {
      "exists": {
       "event": "PRODUCT_SWITCH",
       "within": {
        "ref": "$first_settlement_period"
       },
       "where": {
        "direction": "IN"
       }
      }
     },
     {
      "==": [
       {
        "var": "contract.reference_date"
       },
       {
        "ref": "$first_settlement_period"
       }
      ]
     }
    ]
   },
   "effect": {
    "type": "RESTRICT",
    "target": "RATE_OVERRIDE"
   }
  }
