 "rules": [
  {
   "rule_id": "P111-S2-R08-01",
   "status": "OK",
   "label": "급여이체 우대금리",
   "source": {
    "quote": "급여이체 우대금리 (연 0.5%p) | 적금 가입일이 포함된 달부터 만기 전전월 말일까지 본인 명의 KB국민은행 입출금 통장에 급여주)가 입금된 개월수가 계약기간의 1/2 이상인 경우"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.maturity_date",
       "offset_months": -2,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    ">=": [
     {
      "count_distinct_months": {
       "event": "SALARY_TRANSFER",
       "within": {
        "ref": "$window"
       },
       "where": {
        "or": [
         {
          "and": [
           {
            "var": "SALARY_TRANSFER.source"
           },
           {
            "in": [
             {
              "var": "SALARY_TRANSFER.source"
             },
             [
              "SALARY_CONTRACT"
             ]
            ]
           },
           {
            ">=": [
             {
              "var": "SALARY_TRANSFER.amount"
             },
             200000
            ]
           }
          ]
         },
         {
          ">=": [
           {
            "var": "SALARY_TRANSFER.amount"
           },
           500000
          ]
         }
        ]
       }
      }
     },
     {
      "var": "contract.term_months"
     },
     0.5
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.5,
    "unit": "PERCENTAGE_POINT"
   }
  },
  {
   "rule_id": "P111-S2-R08-02",
   "status": "OK",
